INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/confirmOrders', '샘플 주문 확정', '접수 상태의 주문을 확정으로 옮긴다. 행마다 커밋하고 안 된 행의 사유를 돌려준다.', 'EXECUTE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/exportOrderAll', '샘플 주문 합본 엑셀 — 전체', '조회조건 그대로 전량을 품목과 조인해 한 장으로 만든다. 상한 판정도 서버가 한다.', 'EXPORT', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/exportOrderNoItem', '샘플 주문 엑셀 — 품목 없는 주문', '품목이 하나도 없는 주문만 모아 내린다. 두 그리드 어느 쪽의 조회로도 낼 수 없는 표다.', 'EXPORT', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/exportOrderPage', '샘플 주문 합본 엑셀 — 현재 페이지', '화면이 지목한 주문들을 품목과 조인해 한 장으로 만든다. 화면에 없는 표라 프론트가 만들 수 없다.', 'EXPORT', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/getCustomerList', '샘플 고객 목록 조회', '참조 팝업의 후보를 주문에서 중복 없이 뽑는다. 고객 마스터가 없는 샘플의 대역이다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/getFlatItemList', '샘플 품목 평면 목록 조회', '주문을 가로질러 품목을 오프셋 페이징으로 반환한다. 엑셀 업로드 탭이 기존 행과 대조할 때도 같은 경로를 쓴다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/getItemList', '샘플 주문 품목 조회', '고른 주문 하나의 품목을 순번 순으로 반환한다. 대상은 조회조건이 아니라 파라미터다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/getOrderCursorList', '샘플 주문 목록 조회 — 커서형', '주문일시 기준 커서 페이징으로 반환한다. 총 건수를 세지 않으며 기간이 필수다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/getOrderList', '샘플 주문 목록 조회', '주문번호·고객명·상태·주문일로 걸러 오프셋 페이징으로 반환한다. 삭제 게이트가 읽을 품목 건수를 함께 싣는다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/getOrderOffsetList', '샘플 주문 목록 조회 — 전 컬럼', '조회조건 열둘로 걸러 오프셋 페이징으로 반환한다. 태그는 자식 테이블에서 한 번에 읽어 붙인다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/getTagCandidateList', '샘플 태그 후보 조회', 'listModal 이 고를 태그 후보를 자식 테이블에서 중복 없이 뽑는다. 태그 마스터가 없는 샘플의 대역이다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/getTagList', '샘플 주문 태그 조회', '고른 주문 하나의 태그를 정렬순서대로 반환한다. ①의 list 컬럼과 같은 데이터를 행으로 본다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/recalcItems', '샘플 주문 품목 금액 재계산', '고른 주문마다 딸린 품목의 금액을 수량×단가로 다시 센다. jobId 를 즉시 돌려주고, 진행률은 주문이 바뀔 때마다 소제목과 함께 그 주문의 품목 기준으로 되돌아간다.', 'EXECUTE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/recalculateOrders', '샘플 주문 일괄 재계산', '기준일 이전 주문의 금액을 준 세율로 다시 센다. jobId 를 즉시 돌려주고 작업은 별도 풀에서 돈다.', 'EXECUTE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/saveFlatItems', '샘플 품목 평면 저장', '주문번호와 품목코드로 대상을 가리켜 추가·수정·삭제를 한 트랜잭션으로 반영한다. 없는 주문번호나 겹친 품목코드가 있으면 전부 거절한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/saveItems', '샘플 주문 품목 저장', '고른 주문 하나의 품목을 한 트랜잭션으로 반영한다. 신규 행의 순번은 서버가 정한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/saveOffsetOrders', '샘플 주문 저장 — 전 컬럼', '신규·수정·삭제를 행마다 커밋한다. 실패한 행만 되돌아가고 결과를 건별로 돌려준다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/saveOrders', '샘플 주문 저장', '추가·수정·물리 삭제를 한 트랜잭션으로 반영한다. 품목이 있는 주문의 삭제와 잠긴 주문의 수정을 거부한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/saveTags', '샘플 주문 태그 저장', '고른 주문 하나의 태그를 한 트랜잭션으로 반영한다. 신규 행의 순번은 서버가 정하고 정렬순서가 겹치면 거부한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/sample/service/shipOrders', '샘플 주문 출고 지시', '확정 상태의 주문을 출고로 옮긴다. 하나라도 대상이 아니면 전부 거부한다.', 'EXECUTE', NULL, NULL, NULL, NULL);
INSERT INTO sys_code_group (grp_cd, grp_nm, grp_desc, sys_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('SMPL_ORD_STAT', '샘플 주문상태', '접수 → 확정 → 출고 → 완료. 상태가 편집 가능 여부를 정한다(48 §3.2).', 'N', 900, NULL, NULL, NULL, NULL);
INSERT INTO sys_code_group (grp_cd, grp_nm, grp_desc, sys_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('SMPL_UOM', '샘플 단위', '주문 품목의 수량 단위.', 'N', 901, NULL, NULL, NULL, NULL);
INSERT INTO sys_code_group (grp_cd, grp_nm, grp_desc, sys_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('SMPL_ITEM_STAT', '샘플 품목상태', '품목 한 줄의 진행 상태. 주문 상태와 다른 축이다.', 'N', 902, NULL, NULL, NULL, NULL);
INSERT INTO sys_code_group (grp_cd, grp_nm, grp_desc, sys_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('SMPL_CHNL', '샘플 주문채널', '후보가 스물둘이라 타이핑이 필터다 — richSelect 의 실물(54 §5.7).', 'N', 910, NULL, NULL, NULL, NULL);
INSERT INTO sys_code_group (grp_cd, grp_nm, grp_desc, sys_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('SMPL_PRIORITY', '샘플 우선순위', '아이콘 렌더러가 그리는 코드 — 값이 아이콘을 고른다(54 §5.4).', 'N', 911, NULL, NULL, NULL, NULL);
INSERT INTO sys_code_group (grp_cd, grp_nm, grp_desc, sys_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('SMPL_CUST_GRD', '샘플 고객등급', 'tone 맵의 실물 — 값이 색을 고른다(54 §5.4.1). 팝업이 채우는 칸이다.', 'N', 912, NULL, NULL, NULL, NULL);
INSERT INTO sys_code_group (grp_cd, grp_nm, grp_desc, sys_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('SMPL_TAG_TYPE', '샘플 태그유형', 'list 항목이 스칼라가 아닌 쪽의 실물(54 §5.6).', 'N', 913, NULL, NULL, NULL, NULL);
INSERT INTO sys_code_group (grp_cd, grp_nm, grp_desc, sys_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('SMPL_SRC_SYS', '샘플 원천시스템', '기본 숨김 컬럼이 쓰는 코드 — 설정 창에서 사용자가 켠다(54 §2.1).', 'N', 914, NULL, NULL, NULL, NULL);
INSERT INTO sys_code (grp_cd, dtl_cd, dtl_nm, dtl_desc, sys_yn, use_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('SMPL_ORD_STAT', 'RCV', 'code.SMPL_ORD_STAT.RCV', NULL, 'N', 'Y', 1, NULL, NULL, NULL, NULL);
