INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.cond.itemStat', 'FRONT', '', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.cond.ordAmt', 'FRONT', '', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.duplicated', 'BACK', '이미 있는 주문번호다 — UK_SMPL_ORDER_NO 를 사람이 읽는 문구로 옮긴다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.has-items', 'BACK', '품목이 있는 주문은 지울 수 없다 — frontend/grid.md 의 마스터 삭제 게이트다. 화면이 체크박스를 열지 않지만 그것만으로는 부족하다: 화면 밖 경로가 실재하고, FK 의 RESTRICT 는 제약 위반 이라는 읽을 수 없는 문구로만 답한다(playbook/INDEX.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.item-duplicated', 'BACK', '한 주문에 같은 품목코드가 둘이다 — playbook/INDEX.md. #ERR_SAMPLE_DUPLICATED 는 주문번호 의 중복이라 문구가 그 낱말을 쓴다. 여기서 겹친 것은 주문 안의 품목이며, 파일 안에서 겹쳤을 수도 이미 있는 행과 겹쳤을 수도 있다 — 어느 쪽이든 사용자가 볼 곳은 그 두 줄이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.locked', 'BACK', '잠긴 주문이다 — LOCK_YN 은 상태와 다른 축이다(playbook/INDEX.md). 상태는 일이 어디까지 갔나 이고 이것은 운영이 잠갔나 다. 합치면 완료된 주문의 잠금을 풀 방법이 없어진다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.no-such-order', 'BACK', '엑셀의 주문번호가 DB 에 없다 — playbook/INDEX.md. #ERR_SAMPLE_NOT_FOUND 와 갈라 두는 것은 사용자가 할 일이 다르기 때문이다. 저것은 화면을 다시 조회하세요 이고(남이 지웠다), 이것은 파일의 그 칸을 고치는 일이다 — 다시 조회해 봐야 없는 주문번호는 그대로다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.not-confirmable', 'BACK', '접수 상태가 아니다 — 확정은 RCV 에서만 열린다(playbook/INDEX.md 의 전이표). #ERR_SAMPLE_NOT_SHIPPABLE 과 같은 자리이며, 갈라 두는 것은 사용자가 보는 문장이 어느 전이가 막혔는지를 말해야 하기 때문이다 — 하나로 합치면 상태가 맞지 않습니다 가 되어 무엇을 해야 할지가 사라진다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.not-found', 'BACK', '없는 주문이다 — 화면이 낡았거나 화면 밖 경로다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.not-recalculable', 'BACK', '금액이 잠긴 주문의 품목을 다시 세려 했다 — playbook/INDEX.md 의 행×디테일 재계산. #ERR_SAMPLE_NOT_CONFIRMABLE 와 갈라 두는 것은 사용자가 할 일이 다르기 때문이다. 확정은 지금 하려는 일 이 막힌 것이고, 이쪽은 이미 확정된 금액 이라 막힌 것이다 — 같은 문구로 말하면 확정을 먼저 하라는 뜻으로 읽힌다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.not-shippable', 'BACK', '확정 상태가 아니다 — 출고 지시는 CFM 에서만 열린다(playbook/INDEX.md 의 전이표). 화면이 eligible 로 대상을 거르지만(frontend/grid.md), 고른 뒤 남이 상태를 바꾸면 그 판정은 낡은 값이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.range-required', 'BACK', '기간을 비우고 조회했다 — ②는 기간이 부하의 상한인 화면이다(playbook/INDEX.md · screen/admin/system/log/access/requirements.md). 화면의 required 가 먼저 막지만 도구·스크립트는 그 폼을 지나지 않는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.range-too-wide', 'BACK', '조회 기간이 상한을 넘었다 — 조용히 자르지 않는다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.required', 'BACK', '주문번호·주문명·고객이 비었다 — 셀 단위 오류로 돌려준다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.rmk-required', 'BACK', '할인율이 있는데 비고가 없다 — 조건부 필수(playbook/INDEX.md · frontend/grid.md). #ERR_SAMPLE_REQUIRED 와 갈라 두는 것은 그 문구가 주문번호·주문명·고객· 주문일 넷을 열거하기 때문이다. 조건부 필수를 거기 얹으면 사용자에게 틀린 칸을 가리킨다 — 다 채웠는데 왜 필수라는지 알 수 없고, 그 넷을 다시 들여다보게 된다. 실기동에서 드러났다(2026-09-02). 화면의 required 함수가 먼저 막으므로 평소에는 이 문구가 보이지 않지만, 보이는 순간은 화면 밖 경로라 더 정확해야 한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.tag-required', 'BACK', '태그 행의 필수 — 태그명과 정렬순서(playbook/INDEX.md). #ERR_SAMPLE_REQUIRED 와 갈라 두는 이유가 #ERR_SAMPLE_RMK_REQUIRED 와 같다: 그 문구는 주문 의 넷을 열거하는데 여기서 빈 것은 태그 탭의 행이라, 얹으면 사용자가 마스터를 들여다보게 된다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.tag-sort-duplicated', 'BACK', '태그의 정렬순서가 겹친다 — playbook/INDEX.md. 순서가 값이라서 막는다. 같은 SORT_NO 가 둘이면 읽는 순서가 정해지지 않고, 사용자에게는 고치지도 않았는데 조회할 때마다 태그가 뒤바뀐다 로 보인다 — 그 증상을 없애려고 둔 컬럼이 그 증상을 만들게 된다. DB 의 유일 제약이 아니라 서비스가 막는다. 제약을 걸면 ①의 전량 교체가 같은 트랜잭션 안에서 옛 행과 새 행이 겹치는 순간에 걸리고(지웠다 넣는다), 그 실패는 사용자가 읽을 수 없는 문구로만 답한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.sample.tag-too-many', 'BACK', '한 주문의 태그가 상한을 넘었다 &mdash; 48 &sect;8 의 결정(2026-09-02). 문구가 숫자를 그대로 적는다. 태그가 너무 많습니다 만으로는 몇 개를 빼야 하는지 알 수 없고, 사용자는 하나 지우고 저장하기를 반복한다 &mdash; 56 &sect;3.3 이 건수를 먼저 알려준다 로 정한 것과 같은 이유다. #ERR_SAMPLE_RANGE_TOO_WIDE 가 31일 을 적은 것과 같은 자리이며, 응답 문구는 SYS_MESSAGE 에서 오므로 인자를 끼울 통로가 없다 (BusinessException 은 서버 언어의 로그 문구만 나른다). 저장 둘이 이 문구를 쓴다. &#9312;은 배열의 개수로 &#9316;은 행의 개수로 걸리는데, 사용자에게 사실은 하나다 &mdash; 이 주문에 태그가 몇 개까지 다. 갈라 쓰면 같은 사실이 두 문구로 설명된다. /', NULL, NULL, NULL, NULL);
