INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.action.recalc', 'FRONT', '일괄 재계산 — `target:''all''`, **`params` 모달 + 진행률**(playbook/INDEX.md). 확정과 같은 `X` 액션인데 사용자 경험이 다른 것이 이 화면의 핵심 시연이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.action.recalc.title', 'FRONT', '`params` 모달의 제목이자 진행률 모달의 제목.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.action.recalcItems', 'FRONT', '품목 금액 재계산 버튼 — playbook/INDEX.md 의 실행 둘 중 뒤(행×디테일 진행률). 위의 출고 지시와 같은 자리에 나란히 선다: 같은 `EXECUTE` 이고 같은 `target:''selected''` 인데 하나는 즉시 끝나고 하나는 진행률을 갖는다 — 고른 주문마다 딸린 품목이 수천 건일 수 있어서다(backend/crosscutting.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.action.recalcItems.confirm', 'FRONT', '실행 확인 문구 — `{count}` 는 주문 수다(frontend/grid.md). 품목 건수를 적지 않는다. 그 값은 주문마다 세어야 알 수 있고, 확인 창을 띄우려고 조회를 한 번 더 도는 것은 실행 전에 실행만큼 일하는 꼴이다 — 품목 건수는 진행률 창이 구간마다 말한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.action.recalcItems.hint', 'FRONT', '접수 아닌 행이나 품목 없는 행이 섞였다 — 버튼이 비활성인 이유(frontend/grid.md 의 `hint`). 확정부터는 금액이 잠긴다(playbook/INDEX.md). 화면의 `amountEditable` 이 그렇게 서 있으므로 이 실행이 그 문을 열어 주면 안 된다. /', NULL, NULL, NULL, NULL);
