INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.excel.keyDuplicated', 'FRONT', '파일 안에서 같은 `(주문번호, 품목코드)` 가 두 번이다 — 그리드 층(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.excel.noItem', 'FRONT', '②의 세 번째 항목 — 품목이 없는 주문만 내린다. 조회로는 낼 수 없는 표다: 마스터는 주문을 내고 디테일은 고른 하나의 품목을 내므로, *품목이 하나도 없는 주문들* 은 어느 그리드의 결과도 아니다(playbook/excel-download.md 의 임의 API). /', NULL, NULL, NULL, NULL);
