INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.popup.tag', 'FRONT', '태그 후보 팝업 — 레지스트리 키 `sample.tag` 가 쓰는 제목(playbook/INDEX.md). **`listModal` 의 창과 갈린다.** 저것은 *편집하는 창*(쌓고 순서를 바꾸고 뺀다)이라 제목이 **컬럼 헤더**이고, 이것은 그 위에 뜨는 **고르는 창**이다 — 껍데기가 하나이고 레지스트리가 정하는 것이 후자다(frontend/grid.md). 헤더를 그대로 쓰면 모달 위에 모달이 뜬 화면에서 **제목이 같은 창 둘**이 겹친다. /', NULL, NULL, NULL, NULL);
