INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('sample.tag.tooMany', 'FRONT', '태그가 상한을 넘었다 — playbook/INDEX.md 의 결정. `{max}` 를 채운다. **층이 둘인데 문구는 하나다**(frontend/grid.md) — ①은 컬럼 층에서 배열을 세고 ⑤는 그리드 층에서 행을 세는데, 사용자가 알아야 하는 사실은 *이 주문에 태그가 몇 개까지* 하나다. 서버도 같은 것을 본다(`err.sample.tag-too-many`). /', NULL, NULL, NULL, NULL);
